INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 15, 'theory', 'Квиз: блочные устройства и файловые системы');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 15, 0, 'Почему в /etc/fstab лучше писать UUID=…, а не /dev/sdb1?', '["UUID читается быстрее при загрузке", "Имя sdb1 запрещено в fstab", "Имена sdX выдаются по порядку обнаружения и могут измениться, UUID хранится на диске", "UUID нужен только для swap"]', 2, 'Ядро нумерует диски в порядке обнаружения, и после перезагрузки или добавления диска sdb может стать другим устройством. UUID записан в самой файловой системе и не зависит от порядка.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 15, 1, 'Что верно про таблицу разделов MBR при секторе 512 байт?', '["Предел 2 ТиБ и четыре записи, из которых одна может быть расширенной", "Предел 8 ЗиБ и 128 записей", "Предел 2 ТиБ, но записей сколько угодно", "Предела нет, но нужна защитная GPT"]', 0, 'Адреса секторов в MBR 32-битные: 2^32 секторов по 512 байт дают 2 ТиБ. Основных записей четыре, логические разделы живут внутри расширенной.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 15, 2, 'Какое утверждение о смене размера верно?', '["XFS уменьшают командой xfs_growfs с отрицательным размером", "ext4 можно уменьшать на смонтированной системе", "Сначала уменьшают раздел, затем файловую систему", "XFS можно только увеличивать, ext4 можно и уменьшать, но размонтированной"]', 3, 'В обычной работе XFS уменьшить нельзя, ext4 уменьшают размонтированной после e2fsck. При сжатии сначала файловая система, потом раздел — иначе обрежутся данные.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 15, 3, 'df показывает 100%, а du по всему разделу даёт малую сумму. Какая причина вероятна?', '["Ошибка в таблице разделов", "Удалённый файл, который держит открытым процесс", "Слишком большой размер блока у du", "Включён параметр noatime"]', 1, 'Место удалённого файла освобождается, когда его закроют все процессы. du такого файла не видит, а df считает занятые блоки. Найти его помогает lsof +L1.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 15, 4, 'В fstab есть запись с несуществующим UUID без nofail. Что произойдёт при загрузке?', '["Запись молча пропустится", "Система удалит запись из файла", "Система подождёт устройство (по умолчанию 90 секунд) и уйдёт в аварийный режим", "Система смонтирует другой диск с тем же размером"]', 2, 'Монтирование без nofail обязательно для local-fs.target, а его отказ запускает аварийный режим. С nofail запись только желательна.');
